#pragma once
// Portable. skins.tsv format (tab separated, '#' comment lines):
//   W <TAB> def_index <TAB> internal_name <TAB> label
//   P <TAB> paint_kit_id <TAB> internal_name <TAB> label
// Generated by tools/gen_skins.py from the game's own items_game.txt.
#include <cstdint>
#include <string>
#include <string_view>
#include <vector>

#include "core/ini.hpp"

namespace core {

struct WeaponInfo {
    uint16_t def_index;
    std::string name;
    std::string label;
};
struct PaintKitInfo {
    uint32_t id;
    std::string name;
    std::string label;
};
struct SkinDb {
    std::vector<WeaponInfo> weapons;
    std::vector<PaintKitInfo> kits;
    std::vector<std::string> errors;  // "line N: reason"
};

inline SkinDb parse_skin_db(std::string_view text) {
    SkinDb db;
    size_t pos = 0;
    size_t line_no = 0;
    while (pos <= text.size()) {
        size_t eol = text.find('\n', pos);
        if (eol == std::string_view::npos) eol = text.size();
        std::string_view line = text.substr(pos, eol - pos);
        pos = eol + 1;
        ++line_no;
        if (!line.empty() && line.back() == '\r') line.remove_suffix(1);
        if (line.empty() || line[0] == '#') continue;

        std::string_view cols[4];
        size_t n = 0, start = 0;
        for (size_t i = 0; i <= line.size() && n < 4; ++i) {
            if (i == line.size() || line[i] == '\t') {
                cols[n++] = line.substr(start, i - start);
                start = i + 1;
            }
        }
        auto err = [&](const char* m) { db.errors.push_back("line " + std::to_string(line_no) + ": " + m); };
        if (n < 4) { err("expected 4 tab-separated columns"); continue; }
        auto id = parse_u64(cols[1]);
        if (!id) { err("bad numeric id"); continue; }
        if (cols[0] == "W") {
            if (*id == 0 || *id > 0xFFFF) { err("weapon def index out of range"); continue; }
            db.weapons.push_back({static_cast<uint16_t>(*id), std::string(cols[2]), std::string(cols[3])});
        } else if (cols[0] == "P") {
            if (*id > 0xFFFFFFFFull) { err("paint kit id out of range"); continue; }
            db.kits.push_back({static_cast<uint32_t>(*id), std::string(cols[2]), std::string(cols[3])});
        } else {
            err("unknown record kind");
        }
    }
    return db;
}

}  // namespace core
